  return null;
};

const RestauranteFinanceiro = () => {
  const navigate = useNavigate();
  const pendentesMotoboy = useSolicitacoesMotoboyCount();
  const slugLoja = useMinhaLojaSlug();
  const tipoRestaurante = useTipoRestaurante();

