23	const buildRange = (modo, dia, mes, ano, periodoIni, periodoFim) => {
24	  if (modo === 'dia') return { de: startOf(dia), ate: endOf(dia), label: new Date(dia + 'T12:00:00').toLocaleDateString('pt-BR') };
25	  if (modo === 'mes') {
26	    const [y, m] = mes.split('-');
