29	  }
30	  if (modo === 'ano') return { de: startOf(`${ano}-01-01`), ate: endOf(`${ano}-12-31`), label: `Ano ${ano}` };
31	  if (modo === 'periodo') return { de: startOf(periodoIni), ate: endOf(periodoFim), label: `${new Date(periodoIni + 'T12:00:00').toLocaleDateString('pt-BR')} a ${new Date(periodoFim + 'T12:00:00').toLocaleDateString('pt-BR')}` };
32	  return null;
33	};
