-- Módulo Salão: garçons (staff do restaurante, login próprio via key+senha, criado só pelo dono)
CREATE TABLE IF NOT EXISTS public.garcons (
  id             BIGSERIAL PRIMARY KEY,
  restaurant_id  BIGINT NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
  nome           TEXT NOT NULL,
  telefone       TEXT,
  login_key      TEXT NOT NULL UNIQUE,
  password_hash  TEXT NOT NULL,
  ativo          BOOLEAN NOT NULL DEFAULT true,
  permissoes     JSONB NOT NULL DEFAULT '{"desconto":false,"cancelar":false,"acrescimo":false}'::jsonb,
  ultimo_acesso_em TIMESTAMPTZ,
  created_at     TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_garcons_restaurant ON public.garcons (restaurant_id);

ALTER TABLE public.garcons ENABLE ROW LEVEL SECURITY;

CREATE POLICY garcons_owner ON public.garcons
  FOR ALL USING (
    restaurant_id IN (SELECT id FROM public.restaurants WHERE user_id = auth.uid())
  );

-- Módulo Salão: mesas físicas do restaurante (modo "por mesa")
CREATE TABLE IF NOT EXISTS public.mesas (
  id             BIGSERIAL PRIMARY KEY,
  restaurant_id  BIGINT NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
  numero         INTEGER NOT NULL,
  nome           TEXT,
  status         TEXT NOT NULL DEFAULT 'livre'
                 CHECK (status IN ('livre','ocupada','aguardando_pagamento')),
  created_at     TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE (restaurant_id, numero)
);

CREATE INDEX idx_mesas_restaurant ON public.mesas (restaurant_id);

ALTER TABLE public.mesas ENABLE ROW LEVEL SECURITY;

CREATE POLICY mesas_owner ON public.mesas
  FOR ALL USING (
    restaurant_id IN (SELECT id FROM public.restaurants WHERE user_id = auth.uid())
  );

-- Módulo Salão: comissão de garçom (configurável, múltiplas por restaurante) + lançamentos por comanda fechada
CREATE TABLE IF NOT EXISTS public.garcom_comissoes_config (
  id             BIGSERIAL PRIMARY KEY,
  restaurant_id  BIGINT NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
  nome           TEXT NOT NULL,
  tipo           TEXT NOT NULL CHECK (tipo IN ('percentual','fixo')),
  valor          NUMERIC(10,2) NOT NULL,
  base_calculo   TEXT NOT NULL DEFAULT 'total_vendido' CHECK (base_calculo IN ('total_vendido','total_recebido')),
  ativo          BOOLEAN NOT NULL DEFAULT true,
  created_at     TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_garcom_comissoes_config_restaurant ON public.garcom_comissoes_config (restaurant_id);

ALTER TABLE public.garcom_comissoes_config ENABLE ROW LEVEL SECURITY;

CREATE POLICY garcom_comissoes_config_owner ON public.garcom_comissoes_config
  FOR ALL USING (
    restaurant_id IN (SELECT id FROM public.restaurants WHERE user_id = auth.uid())
  );

CREATE TABLE IF NOT EXISTS public.garcom_comissoes_lancamentos (
  id             BIGSERIAL PRIMARY KEY,
  garcom_id      BIGINT NOT NULL REFERENCES public.garcons(id) ON DELETE CASCADE,
  order_id       BIGINT NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  config_id      BIGINT REFERENCES public.garcom_comissoes_config(id) ON DELETE SET NULL,
  valor_calculado NUMERIC(10,2) NOT NULL,
  criado_em      TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE (order_id, config_id)
);

CREATE INDEX idx_garcom_comissoes_lancamentos_garcom ON public.garcom_comissoes_lancamentos (garcom_id);

ALTER TABLE public.garcom_comissoes_lancamentos ENABLE ROW LEVEL SECURITY;

CREATE POLICY garcom_comissoes_lancamentos_owner ON public.garcom_comissoes_lancamentos
  FOR ALL USING (
    garcom_id IN (
      SELECT id FROM public.garcons WHERE restaurant_id IN (
        SELECT id FROM public.restaurants WHERE user_id = auth.uid()
      )
    )
  );

-- Módulo Salão: numeração de comanda (sequencial por dia) + config de gorjeta do estabelecimento
ALTER TABLE public.orders
  ADD COLUMN IF NOT EXISTS numero_comanda INTEGER;

ALTER TABLE public.restaurants
  ADD COLUMN IF NOT EXISTS gorjeta_percentual NUMERIC(5,2) NOT NULL DEFAULT 0;

-- Módulo Salão: pagamentos parciais de uma comanda (garçom ou caixa podem registrar)
CREATE TABLE IF NOT EXISTS public.comanda_pagamentos (
  id             BIGSERIAL PRIMARY KEY,
  order_id       BIGINT NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  valor          NUMERIC(10,2) NOT NULL,
  forma_pagamento TEXT NOT NULL,
  origem         TEXT NOT NULL CHECK (origem IN ('garcom','estabelecimento')),
  criado_em      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_comanda_pagamentos_order ON public.comanda_pagamentos (order_id);

ALTER TABLE public.comanda_pagamentos ENABLE ROW LEVEL SECURITY;

CREATE POLICY comanda_pagamentos_owner ON public.comanda_pagamentos
  FOR ALL USING (
    order_id IN (
      SELECT id FROM public.orders WHERE restaurant_id IN (
        SELECT id FROM public.restaurants WHERE user_id = auth.uid()
      )
    )
  );

