1	import React, { useState, useEffect } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import {
4	  getMeusProdutos, criarProduto, editarProduto, deletarProduto, toggleProduto,
5	  getMinhasCategorias, getCategoriasGlobais, criarCategoria, deletarCategoria,
6	  getTagsPublicas, listarImpressoras,
7	} from '../../services/restauranteService';
8	import { useAuth } from '../../contexts/AuthContext';
9	import Icon from '../../components/AppIcon';
10	import ImageUpload from '../../components/ui/ImageUpload';
11	import { useMinhaLojaSlug } from '../../hooks/useMinhaLojaSlug';
12	import { useTipoRestaurante } from '../../hooks/useTipoRestaurante';
13	
14	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
15	
16	const EMPTY_FORM = { name: '', description: '', price: '', preco_promo: '', image_url: '', category_id: '', tags: [], destaque: false, impressora_id: '' };
17	
18	const TagBadge = ({ slug, tagsMap }) => {
19	  const t = tagsMap[slug];
20	  if (!t) return <span className="text-xs px-1.5 py-0.5 rounded font-bold bg-gray-100 text-gray-600">{slug}</span>;
21	  return <span className="text-xs px-1.5 py-0.5 rounded font-bold bg-orange-100 text-orange-700">{t.name}</span>;
22	};
23	
24	const RestauranteProdutos = () => {
25	  const navigate = useNavigate();
26	  const { signOut } = useAuth();
27	  const [produtos, setProdutos] = useState([]);
28	  const [categorias, setCategorias] = useState([]);
29	  const [categoriasGlobais, setCategoriasGlobais] = useState([]);
30	  const [tagsDisponiveis, setTagsDisponiveis] = useState([]); // tags não-auto do admin
31	  const [impressoras, setImpressoras] = useState([]);
32	  const tipoRestaurante = useTipoRestaurante();
33	  const [novaCategoria, setNovaCategoria] = useState('');
34	  const [criandoCateg, setCriandoCateg] = useState(false);
35	  const [deletandoCateg, setDeletandoCateg] = useState(null);
36	  const [showCategPanel, setShowCategPanel] = useState(false);
37	  const [loading, setLoading] = useState(true);
38	  const [erro, setErro] = useState(null);
39	  const [showModal, setShowModal] = useState(false);
40	  const [editando, setEditando] = useState(null);
41	  const [form, setForm] = useState(EMPTY_FORM);
42	  const [salvando, setSalvando] = useState(false);
43	  const [deletando, setDeletando] = useState(null);
44	
45	  const carregar = () => {
46	    setLoading(true);
